<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Rankings</title><link rel='stylesheet' href='/assets/css/ui.css'><link rel='stylesheet' href='/assets/css/components.css'><link rel='stylesheet' href='https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css'></head><body><script src='/assets/js/ui.js'></script><script>
UX.shell('/rankings',`<div class='hero'><h2>Global Rankings</h2><div style='display:flex;gap:8px'><input id='q' class='search' placeholder='Search'><select id='sort' class='search'><option value='desc'>Desc</option><option value='asc'>Asc</option></select></div></div><div class='glass-card'><div class='tabs'><button class='tab active' data-t='regions'>Regions</button><button class='tab' data-t='countries'>Countries</button><button class='tab' data-t='players'>Players</button></div><table class='table' id='table'><thead><tr><th>#</th><th>Name</th><th>Score</th></tr></thead><tbody id='rows'><tr><td colspan='3'><div class='skeleton'></div></td></tr></tbody></table></div>`);
let tab='regions', data={regions:[],countries:[],players:[]};
const color=v=>v<=2?'stat-red':v<=5?'stat-yellow':'stat-green';
(async()=>{const d=await UX.api('/api/stats/dashboard');data.regions=d.top_regions||[];data.countries=d.top_countries||[];data.players=(d.top_region_population||[]).map(x=>({id:x.id,name:'Player @'+x.name,score:Number(x.total_population||0)}));render();})();
function render(){const s=(q.value||'').toLowerCase();const asc=sort.value==='asc';let arr=(data[tab]||[]).filter(x=>JSON.stringify(x).toLowerCase().includes(s));arr.sort((a,b)=>asc?(Number(a.score||a.total_score||0)-Number(b.score||b.total_score||0)):(Number(b.score||b.total_score||0)-Number(a.score||a.total_score||0)));rows.innerHTML=arr.map((r,i)=>{const val=Number(r.score||r.total_score||0),name=r.name||r.country_name||r.name;const href=tab==='regions'?`/region/${r.id}`:tab==='countries'?`/country/${r.id}`:`/player/${r.id}`;return `<tr><td>${i+1}</td><td><a href='${href}'>${name}</a></td><td class='${color(val)}'>${UX.fmt(val)}</td></tr>`;}).join('');}
document.querySelectorAll('[data-t]').forEach(b=>b.onclick=()=>{tab=b.dataset.t;document.querySelectorAll('[data-t]').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();});q.oninput=render;sort.onchange=render;
</script></body></html>
